query:
PREFIX marcrel: <http://id.loc.gov/vocabulary/relators/>
PREFIX dcterms: <http://purl.org/dc/terms/>
PREFIX skos: <http://www.w3.org/2004/02/skos/core#>
SELECT DISTINCT ?doc ?citation ?subject ?subjectLabel WHERE {
 ?doc marcrel:aut <http://www.idref.fr/242228119/id> .
 OPTIONAL { ?doc dcterms:bibliographicCitation ?citation }
 ?doc dcterms:subject ?subject . OPTIONAL { ?subject skos:prefLabel ?subjectLabel }
} LIMIT 100
